function variance(){const t=today(),from=ui.varianceFrom||`${t.slice(0,8)}01`,to=ui.varianceTo||t,p=RayoInventoryV10.periodMetrics(from,to);return `<div class="card"><div class="section-head"><div><h2>مغایرت و اثر واقعی بهای مواد</h2><p class="muted">مصرف استاندارد، پرتی/شکستگی و مغایرت فیزیکی در بازه انتخابی.</p></div><a class="btn" href="reports.html?tab=inventoryLoss&from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}">نمای گزارش</a></div><div class="toolbar"><div class="field"><label>از تاریخ</label><input data-jalali="1" value="${E(from)}" onchange="RayoInventoryV1012.varianceFrom(this.value)"></div><div class="field"><label>تا تاریخ</label><input data-jalali="1" value="${E(to)}" onchange="RayoInventoryV1012.varianceTo(this.value)"></div></div></div><div class="v1012-report-grid"><div class="card kpi"><div class="label">بهای استاندارد</div><div class="value">${M(p.standard)}</div><div class="sub">${F(p.standardPct,2)}٪ فروش</div></div><div class="card kpi"><div class="label">پرتی و شکستگی</div><div class="value">${M(p.waste)}</div><div class="sub">${F(p.wastePct,2)}٪ فروش</div></div><div class="card kpi"><div class="label">مغایرت نامشخص</div><div class="value">${M(p.unexplained)}</div><div class="sub">${F(p.variancePct,2)}٪ فروش</div></div><div class="card kpi"><div class="label">بهای واقعی مواد</div><div class="value">${M(p.actualCogs)}</div><div class="sub">${F(p.actualPct,2)}٪ فروش</div></div></div>${core('history')}`}
function reorder(){const q=S(ui.reorderSearch).toLowerCase(),rels=A(suppliers()?.supplierItems),rows=ingredients().map(i=>{const tr=A(inv()?.trackedIngredients).find(x=>x.ingredientId===i.id)||{},pos=RayoInventoryV10.currentTotalPosition(i.id),assessment=window.RayoReorder?.assess?.(i,inv(),pos)||{point:null,need:false},target=Object.prototype.hasOwnProperty.call(i,'targetStock')?N(i.targetStock):Object.prototype.hasOwnProperty.call(tr,'targetStock')?N(tr.targetStock):null,quotes=rels.filter(x=>x.itemId===i.id||x.ingredientId===i.id);return{i,pos,point:assessment.point,target,quotes,need:assessment.need}}).filter(x=>x.need&&(!q||`${x.i.name} ${x.i.code||''}`.toLowerCase().includes(q))).sort((a,b)=>(a.pos.quantity-a.point)-(b.pos.quantity-b.point));return `<div class="card"><div class="section-head"><div><h2>اقلام نیازمند سفارش</h2><p class="muted">موجودی مجموع همه محل‌ها در واحد مبنای قلم، کمتر یا مساوی نقطه سفارش است.</p></div></div><div class="toolbar"><div class="field v1012-search"><label>جست‌وجو</label><input value="${E(ui.reorderSearch)}" oninput="RayoInventoryV1012.reorderSearch(this.value)" placeholder="نام یا کد قلم"></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>قلم</th><th>موجودی</th><th>نقطه سفارش</th><th>واحد</th><th>تا هدف</th><th>تأمین‌کننده‌ها</th></tr></thead><tbody>${rows.map(x=>`<tr data-v1012-stock-row data-search="${E((x.i.name+' '+(x.i.code||'')).toLowerCase())}"><td><b>${E(x.i.name)}</b><br><small>${E(x.i.code||'')}</small></td><td class="v1012-negative">${F(x.pos.quantity,3)}</td><td>${F(x.point,3)}</td><td>${E(x.i.recipeUnit||'واحد')}</td><td>${x.target===null?'—':F(Math.max(0,x.target-x.pos.quantity),3)}</td><td>${x.quotes.length?F(x.quotes.length,0):'<span class="badge warn">تعریف نشده</span>'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">قلمی به نقطه سفارش نرسیده است یا نقطه سفارش ندارد.</td></tr>'}</tbody></table></div></div>`}
