function itemDetail(id){const i=ing(id);if(!i)return toast('قلم موردنظر پیدا نشد',true);const rows=locs().map(l=>({l,p:RayoInventoryV10.positionAtLocation(id,l.id)}));RayoInventoryV10.openModal(`موجودی ${i.name}`,`<div class="table-wrap"><table class="data-table"><thead><tr><th>محل</th><th>موجودی</th><th>واحد</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${E(x.l.name)}</td><td>${F(x.p.quantity,3)}</td><td>${E(i.recipeUnit||'واحد')}</td><td><button class="btn btn-sm" onclick="closeModal();RayoInventoryV10.drill('${E(id)}','${E(x.l.id)}')">گردش</button></td></tr>`).join('')}</tbody></table></div>`,`<button class="btn" onclick="closeModal()">بستن</button>`)}
